input_data = sys.stdin.read().split('\n')
text1 = input_data[0].strip()
text2 = input_data[1].strip()

@lru_cache(maxsize=None)
def lcs(i, j):
    if i == len(text1) or j == len(text2):
        return 0
    if text1[i] == text2[j]:
        return 1 + lcs(i+1, j+1)
    return max(lcs(i+1, j), lcs(i, j+1))

