import java.util.*;
public class Solution {
    static String t1, t2;
    static int[][] memo;
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        t1 = sc.nextLine().trim();
        t2 = sc.nextLine().trim();
        memo = new int[t1.length()][t2.length()];
        for (int[] row : memo) Arrays.fill(row, -1);
        System.out.println(lcs(0, 0));
    }
    static int lcs(int i, int j) {
        if (i == t1.length() || j == t2.length()) return 0;
        if (memo[i][j] != -1) return memo[i][j];
        if (t1.charAt(i) == t2.charAt(j)) return memo[i][j] = 1 + lcs(i+1, j+1);
        return memo[i][j] = Math.max(lcs(i+1, j), lcs(i, j+1));
    }
}

import java.util.*;
public class Solution {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String t1 = sc.nextLine().trim();
        String t2 = sc.nextLine().trim();
        int m = t1.length(), n = t2.length();
        int[][] dp = new int[m+1][n+1];
        for (int i = m-1; i >= 0; i--)
            for (int j = n-1; j >= 0; j--)
                dp[i][j] = t1.charAt(i) == t2.charAt(j) ? 1 + dp[i+1][j+1] : Math.max(dp[i+1][j], dp[i][j+1]);
        System.out.println(dp[0][0]);
    }
}

